declare_lint ! { # [doc = " The `let_underscore_lock` lint checks for statements which don't bind"] # [doc = " a mutex to anything, causing the lock to be released immediately instead"] # [doc = " of at end of scope, which is typically incorrect."] # [doc = ""] # [doc = " ### Example"] # [doc = " ```rust,compile_fail"] # [doc = " use std::sync::{Arc, Mutex};"] # [doc = " use std::thread;"] # [doc = " let data = Arc::new(Mutex::new(0));"] # [doc = ""] # [doc = " thread::spawn(move || {"] # [doc = "     // The lock is immediately released instead of at the end of the"] # [doc = "     // scope, which is probably not intended."] # [doc = "     let _ = data.lock().unwrap();"] # [doc = "     println!(\"doing some work\");"] # [doc = "     let mut lock = data.lock().unwrap();"] # [doc = "     *lock += 1;"] # [doc = " });"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Statements which assign an expression to an underscore causes the"] # [doc = " expression to immediately drop instead of extending the expression's"] # [doc = " lifetime to the end of the scope. This is usually unintended,"] # [doc = " especially for types like `MutexGuard`, which are typically used to"] # [doc = " lock a mutex for the duration of an entire scope."] # [doc = ""] # [doc = " If you want to extend the expression's lifetime to the end of the scope,"] # [doc = " assign an underscore-prefixed name (such as `_foo`) to the expression."] # [doc = " If you do actually want to drop the expression immediately, then"] # [doc = " calling `std::mem::drop` on the expression is clearer and helps convey"] # [doc = " intent."] pub LET_UNDERSCORE_LOCK , Deny , "non-binding let on a synchronization lock" }